@Component({
    selector: 'app-etudiant-Create',
    imports: [CommonModule, MaterialModule],
    templateUrl: './etuCreate.component.html',
    standalone: true,
    styleUrl: './etuCreate.component.css'
})
export class EtuCreateComponent implements OnInit {
    private formBuilder = inject(FormBuilder);
    private etudiantService = inject(EtudiantService)
    private router = inject(Router);
    private destroyRef = inject(DestroyRef);
    createForm: FormGroup = new FormGroup({});
    submitted: boolean = false;

    ngOnInit() {
        this.createForm = this.formBuilder.group({
            firstName: ['', Validators.required],
            lastName: ['',Validators.required],
            email: ['', [Validators.required, Validators.email]]
        })
    }

    get form() {
        return this.createForm.controls;
    }

    onSubmit(): void {
        this.submitted = true;
        if (this.createForm.invalid) {
            return;
        }
        const newEtudiant: Etudiant = {
            firstName: this.createForm.get('firstName')?.value,
            lastName: this.createForm.get('lastName')?.value,
            email: this.createForm.get('email')?.value
        }
        this.etudiantService.createEtudiant(newEtudiant)
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe({
                next: () => {
                    this.router.navigate(['/etudiant']);
                },
                error: (error) => {
                    this.createForm.get('email')?.setErrors({
                        emailExists: true
                    });
                }
            });
    }

    onReset(): void {
        this.submitted = false;
        this.createForm.reset();
    }

}

import { Component, OnInit, inject, DestroyRef } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { Router, ActivatedRoute } from '@angular/router';
import { MaterialModule } from '../../../shared/material.module';
import { EtudiantService } from '../../../core/service/etudiant.service';
import { Etudiant } from '../../../core/models/Etudiant';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';

@Component({
    selector: 'app-etudiant-update',
    imports: [CommonModule, MaterialModule],
    templateUrl: './etuUpdate.component.html',
    standalone: true,
    styleUrl: './etuUpdate.component.css'
})
export class EtuUpdateComponent implements OnInit {
    private formBuilder = inject(FormBuilder);
    private etudiantService = inject(EtudiantService)
    private router = inject(Router)
    private route = inject(ActivatedRoute);
    private destroyRef = inject(DestroyRef);
    updateForm: FormGroup = new FormGroup({});
    etudiant: Etudiant | null = null;
    submitted: boolean = false;


    ngOnInit() {
        this.updateForm = this.formBuilder.group({
            firstName: ['', Validators.required],
            lastName: ['', Validators.required],
            email: ['', [Validators.required, Validators.email]]
        });
        this.route.paramMap
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe(params => {
                const id = Number(params.get('id'));
                this.etudiantService.getEtudiantById(id)
                    .pipe(takeUntilDestroyed(this.destroyRef))
                    .subscribe({
                        next: (etudiant: Etudiant) => {
                            this.etudiant = etudiant;
                            this.updateForm.patchValue({
                                firstName: etudiant.firstName,
                                lastName: etudiant.lastName,
                                email: etudiant.email
                            });
                        },
                        error: () => {
                            this.router.navigate(['/etudiant']);
                        }
                    });
            });
    }

    get form() {
        return this.updateForm.controls;
    }

    onSubmit(): void {
        this.submitted = true;
        if (this.updateForm.invalid || !this.etudiant) {
            return;
        }
        const updatedEtudiant: Etudiant = {
            firstName: this.updateForm.get('firstName')?.value,
            lastName: this.updateForm.get('lastName')?.value,
            email: this.updateForm.get('email')?.value
        }
        this.etudiantService.updateEtudiant(this.etudiant!.id!, updatedEtudiant)
            .pipe(takeUntilDestroyed(this.destroyRef))
            .subscribe({
                next: () => {
                    this.router.navigate(['/etudiant']);
                },
                error: (error) => {
                    this.updateForm.get('email')?.setErrors({
                        emailExists: true
                    });
                }
            });
    }

    goBack(): void {
        this.router.navigate(['/etudiant']);
    }
}

import { Component, OnInit, inject, DestroyRef } from '@angular/core';
